    def all_datacenter_host_tasks(
        self,
        service_name: str,
        datacenter_id: int,
        host_id: int,
        *,
        name: str | None | NotGiven = NOT_GIVEN,
        state: models.DedicatedCloudTaskStateEnum | str | None | NotGiven = NOT_GIVEN,
    ) -> t.Iterator[models.DedicatedCloudTask]:
        """all_datacenter_host_tasks iterates over GET /v1/dedicatedCloud/{serviceName}/datacenter/{datacenterId}/host/{hostId}/task (List host tasks).

        It lists the IDs with list_datacenter_host_tasks, then gets each object with get_datacenter_host_task,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop.

        Args:
            service_name: Domain of the service
            datacenter_id: Id of the Datacenter
            host_id: Id of the host
            name: Filter the value of name property (like) (optional)
            state: Filter the value of state property (=) (optional)

        The two calls require the IAM action pccVMware:apiovh:datacenter/host/task/get.
        """
        return self._each(
            lambda: self.list_datacenter_host_tasks(
                service_name,
                datacenter_id,
                host_id,
                name=name,
                state=state,
            ),
            lambda listed_id: self.get_datacenter_host_task(
                service_name, datacenter_id, host_id, listed_id
            ),
        )

