    def all_filer_tasks(
        self,
        service_name: str,
        filer_id: int,
        *,
        name: str | None | NotGiven = NOT_GIVEN,
        state: models.DedicatedCloudTaskStateEnum | str | None | NotGiven = NOT_GIVEN,
    ) -> t.Iterator[models.DedicatedCloudTask]:
        """all_filer_tasks iterates over GET /v1/dedicatedCloud/{serviceName}/filer/{filerId}/task (List datastore tasks).

        It lists the IDs with list_filer_tasks, then gets each object with get_filer_task,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop.

        Args:
            service_name: Domain of the service
            filer_id: Filer Id
            name: Filter the value of name property (like) (optional)
            state: Filter the value of state property (=) (optional)

        The two calls require the IAM action pccVMware:apiovh:filer/task/get.
        """
        return self._each(
            lambda: self.list_filer_tasks(
                service_name,
                filer_id,
                name=name,
                state=state,
            ),
            lambda listed_id: self.get_filer_task(service_name, filer_id, listed_id),
        )

